#include "ReferenceComparison.h"
#include "ProjectAssets.h"
#include "WaveTools.h"
#include <cmath>
namespace pulse {
using namespace juce;
namespace {
String stamp(const File& f){return f.getFullPathName()+"|"+String(f.getSize())+"|"+String(f.getLastModificationTime().toMilliseconds());}
double db(double n){return n>1e-8?20*std::log10(n):-160;}
double rms(const MixMeasurements& m){return std::hypot(m.rms[0],m.rms[1])/std::sqrt(2.);}
double peak(const MixMeasurements& m){return jmax(m.peak[0],m.peak[1]);}
bool stopped(const std::atomic<bool>* cancel){return cancel&&cancel->load();}
Result signatures(const Project& p,const File& base,const File& reference,AssetFingerprints& out,const std::atomic<bool>* cancel){
    std::vector<File> files{reference};for(const auto& a:projectAssets(p,base))if(a.file!=File()&&std::find(files.begin(),files.end(),a.file)==files.end())files.push_back(a.file);
    int64 total=0;AssetFingerprints next;for(const auto& f:files){auto size=f.getSize();if(size<0||size>maxFingerprintPassBytes-total)return Result::fail("Reference comparison exceeds the 2 GiB verification budget.");total+=size;AssetFingerprint a;auto valid=fingerprintAssetFile(f,a,cancel);if(valid.failed())return valid;next.push_back(std::move(a));}out=std::move(next);return Result::ok();
}
Result measure(const AudioBuffer<float>& audio,MixMeasurements& out,const std::atomic<bool>* cancel){auto meter=std::make_unique<MixMeter>();for(int i=0;i<audio.getNumSamples();++i){if((i&4095)==0&&stopped(cancel))return Result::fail("Reference comparison cancelled.");if(!meter->feed(audio.getSample(0,i),audio.getSample(1,i)))return Result::fail("Non-finite comparison audio.");}out=meter->finish();return Result::ok();}
Result write(const File& file,const AudioBuffer<float>& audio,const std::atomic<bool>* cancel){
    TemporaryFile temp(file);std::unique_ptr<OutputStream> stream(temp.getFile().createOutputStream());WavAudioFormat format;
    auto writer=stream?format.createWriterFor(stream,AudioFormatWriterOptions{}.withSampleRate(48000).withNumChannels(2).withBitsPerSample(32).withSampleFormat(AudioFormatWriterOptions::SampleFormat::floatingPoint)):nullptr;
    if(!writer)return Result::fail("Cannot create reference audition copy.");for(int i=0;i<audio.getNumSamples();i+=4096){if(stopped(cancel))return Result::fail("Reference comparison cancelled.");if(!writer->writeFromAudioSampleBuffer(audio,i,jmin(4096,audio.getNumSamples()-i)))return Result::fail("Cannot write reference audition copy.");}writer.reset();stream.reset();if(stopped(cancel))return Result::fail("Reference comparison cancelled.");return temp.overwriteTargetFileWithTemporary()?Result::ok():Result::fail("Cannot publish reference audition copy.");
}
bool validMeasurement(const MixMeasurements& m){if(!m.frames||m.frames>48000*60ULL||!std::isfinite(m.correlation)||std::abs(m.correlation)>1)return false;for(int c=0;c<2;++c)if(!std::isfinite(m.peak[c])||m.peak[c]<0||!std::isfinite(m.rms[c])||m.rms[c]<0||m.rms[c]>m.peak[c]+1e-6||!std::isfinite(m.dc[c])||std::abs(m.dc[c])>m.peak[c]+1e-6||m.fullScale[c]>m.frames)return false;for(auto f:m.bandFraction)if(!std::isfinite(f)||f<0||f>1)return false;return true;}
var measurements(const MixMeasurements& m){auto* o=new DynamicObject();auto array=[](const auto& a){Array<var> v;for(auto x:a)v.add(var(x));return var(v);};o->setProperty("frames",(int64)m.frames);o->setProperty("peak",array(m.peak));o->setProperty("rms",array(m.rms));o->setProperty("dc",array(m.dc));o->setProperty("bandFraction",array(m.bandFraction));o->setProperty("correlation",m.correlation);o->setProperty("correlationValid",m.correlationValid);Array<var> clips;for(auto x:m.fullScale)clips.add((int64)x);o->setProperty("fullScaleSamples",clips);return var(o);}
}
Result validateReferenceOptions(const ReferenceOptions& o){return std::isfinite(o.mixBeat)&&o.mixBeat>=0&&o.mixBeat<=8192&&std::isfinite(o.referenceSeconds)&&o.referenceSeconds>=0&&o.referenceSeconds<=86400&&std::isfinite(o.duration)&&o.duration>=.25&&o.duration<=60?Result::ok():Result::fail("Use a nonnegative mix beat/reference offset and a 0.25-60 second passage.");}
std::array<float,2> referenceGains(const ReferenceReport& r,bool match){
    double a=1,b=1,ra=rms(r.mix),rb=rms(r.reference);if(match&&ra>1e-8&&rb>1e-8){double target=jmin(ra,rb);a=target/ra;b=target/rb;}
    double top=jmax(peak(r.mix)*a,peak(r.reference)*b),common=jmin(.7,top>0?.98/top:.7);return{(float)(a*common),(float)(b*common)};
}
String referenceSummary(const ReferenceReport& r){
    auto gains=referenceGains(r,true);String text="A: "+r.title+" / "+String(r.songMode?"Song":"Pattern")+" from beat "+String(r.options.mixBeat,3)+" (zero-based)\nB: "+r.referenceFile.getFileName()+" from "+String(r.options.referenceSeconds,3)+" s\nBoth: "+String(r.mix.frames/48000.,3)+" s / 48 kHz stereo / no extra tail\n\n";
    auto line=[&](const String& label,double a,double b,const String& unit){text+=label+"\n  Mix: "+String(a,2)+" "+unit+"     Reference: "+String(b,2)+" "+unit+"\n";};
    line("Sample peak",db(peak(r.mix)),db(peak(r.reference)),"dBFS");line("Combined stereo RMS",db(rms(r.mix)),db(rms(r.reference)),"dBFS");line("Crest factor",jmax(0.,db(peak(r.mix))-db(rms(r.mix))),jmax(0.,db(peak(r.reference))-db(rms(r.reference))),"dB");
    text+="Full-scale samples L/R: mix "+String((int64)r.mix.fullScale[0])+"/"+String((int64)r.mix.fullScale[1])+"; reference "+String((int64)r.reference.fullScale[0])+"/"+String((int64)r.reference.fullScale[1])+"\nStereo correlation: mix "+(r.mix.correlationValid?String(r.mix.correlation,3):"unavailable")+"; reference "+(r.reference.correlationValid?String(r.reference.correlation,3):"unavailable")+"\n\nStereo FFT power balance (descriptive):\n";
    const char* bands[]={"20-200 Hz","200-4000 Hz","4-20 kHz"};for(int i=0;i<3;++i)line(bands[i],r.mix.bandFraction[i]*100,r.reference.bandFraction[i]*100,"%");
    text+="\nRMS matching attenuates the louder passage; neither side is boosted. Shared headroom attenuation protects both auditions. Matched gains A/B: "+String(gains[0],6)+" / "+String(gains[1],6)+".\n";
    if(rms(r.mix)<=1e-8||rms(r.reference)<=1e-8)text+="One passage is silent: level matching is unavailable; common attenuation only.\n";
    text+="\nA/B starts each passage at its beginning and stops Song playback. Mix includes its rendered Master chain; the reference bypasses it. No project edit, Undo, EQ correction or export inclusion. Measurements are sample peaks, RMS and FFT2048 Hann power, not LUFS/true peak or a mastering target. Looping, continuous-position switching and selectable reference processing remain planned.";return text;
}
var referenceToJson(const ReferenceReport& r){auto* o=new DynamicObject();o->setProperty("schema",1);o->setProperty("application","Pulse Studio reference comparison");o->setProperty("projectHash",r.projectHash);o->setProperty("referenceHash",r.referenceHash);o->setProperty("referencePath",r.referenceFile.getFullPathName());o->setProperty("title",r.title);o->setProperty("songMode",r.songMode);o->setProperty("mixBeat",r.options.mixBeat);o->setProperty("referenceSeconds",r.options.referenceSeconds);o->setProperty("duration",r.options.duration);o->setProperty("sampleRate",48000);o->setProperty("mix",measurements(r.mix));o->setProperty("reference",measurements(r.reference));auto gains=referenceGains(r,true);Array<var> g;for(auto x:gains)g.add(x);o->setProperty("matchedGains",g);o->setProperty("summary",referenceSummary(r));return var(o);}
Result saveReferenceReport(const File& file,const ReferenceReport& r){if(validateReferenceOptions(r.options).failed()||!validMeasurement(r.mix)||!validMeasurement(r.reference)||r.mix.frames!=r.reference.frames||r.projectHash.length()!=64||r.referenceHash.length()!=64)return Result::fail("Invalid reference report. Previous report retained.");auto text=JSON::toString(referenceToJson(r),false,22);if(text.getNumBytesAsUTF8()>1024*1024)return Result::fail("Reference report is too large.");auto result=file.getParentDirectory().createDirectory();if(result.failed())return result;TemporaryFile temp(file);if(!temp.getFile().replaceWithText(text)||temp.getFile().loadFileAsString()!=text||!temp.overwriteTargetFileWithTemporary())return Result::fail("Cannot save reference report. Previous report retained.");return Result::ok();}
Result compareReference(const Project& project,const File& base,const File& reference,const ReferenceOptions& options,const File& directory,ReferenceReport& output,std::atomic<bool>* cancel,std::atomic<float>* progress){
    if(progress)progress->store(0);auto valid=validateReferenceOptions(options);if(valid.failed())return valid;if(stopped(cancel))return Result::fail("Reference comparison cancelled.");if(directory.exists())return Result::fail("Comparison requires a new private audition directory.");
    Project checked;valid=projectFromJson(projectToJson(project),checked);if(valid.failed())return valid;RenderSettings settings;settings.bits=32;settings.tailSeconds=0;settings.startBeat=options.mixBeat;settings.endBeat=options.mixBeat+options.duration*project.bpm/60;RenderPlan plan;valid=planRender(project,settings,plan);if(valid.failed())return valid;if(plan.endFrame>48000*600LL||plan.outputFrames>48000*60LL)return Result::fail("Choose a passage of at most 60 seconds ending within the first ten minutes.");
    ReferenceReport report;report.options=options;report.referenceFile=reference;report.title=project.title;report.songMode=plan.songMode;report.projectHash=mixProjectHash(project,base);valid=signatures(project,base,reference,report.sources,cancel);if(valid.failed())return valid;report.referenceHash=report.sources[0].hash;
    AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(reference));if(!reader||reader->numChannels<1||reader->numChannels>2||!std::isfinite(reader->sampleRate)||reader->sampleRate<8000||reader->sampleRate>192000)return Result::fail("Choose mono/stereo audio at 8-192 kHz.");
    auto first=(int64)std::ceil(options.referenceSeconds*reader->sampleRate-1e-7);int count=(int)std::ceil(plan.outputFrames*reader->sampleRate/48000.);if(first<0||first>reader->lengthInSamples-count)return Result::fail("Reference passage extends beyond the source audio.");
    AudioBuffer<float> native(2,count);for(int at=0;at<count;at+=4096){if(stopped(cancel))return Result::fail("Reference comparison cancelled.");if(!reader->read(&native,at,jmin(4096,count-at),first+at,true,true))return Result::fail("Cannot decode reference passage.");}if(reader->numChannels==1)native.copyFrom(1,0,native,0,0,count);
    AudioBuffer<float> converted;valid=resampleWave(native,reader->sampleRate,48000,converted,[&]{return stopped(cancel);});if(valid.failed())return valid;if(converted.getNumSamples()<plan.outputFrames)return Result::fail("Reference conversion produced a short passage.");converted.setSize(2,(int)plan.outputFrames,true,false,true);valid=measure(converted,report.reference,cancel);if(valid.failed())return valid;
    if(progress)progress->store(.2f);valid=directory.createDirectory();if(valid.failed())return valid;
    struct Cleanup {File folder,mix,ref;bool keep=false;~Cleanup(){if(!keep){mix.deleteFile();ref.deleteFile();folder.deleteFile();}}} cleanup{directory,directory.getChildFile("mix.wav"),directory.getChildFile("reference.wav")};
    report.mixFile=cleanup.mix;report.referenceCopy=cleanup.ref;Assets assets;valid=renderAudio(project,assets,base,report.mixFile,settings,-1,cancel);if(valid.failed())return valid;if(progress)progress->store(.75f);String error;auto* mix=assets.load(report.mixFile,error);if(!mix)return Result::fail(error);if(mix->audio.getNumSamples()!=plan.outputFrames)return Result::fail("Comparison render length changed.");valid=measure(mix->audio,report.mix,cancel);if(valid.failed())return valid;
    valid=write(report.referenceCopy,converted,cancel);if(valid.failed())return valid;AssetFingerprints after;valid=signatures(project,base,reference,after,cancel);if(valid.failed())return valid;if(!sameMixAssets(report.sources,after))return Result::fail("Project/reference audio changed while comparing. Rebuild the comparison.");if(stopped(cancel))return Result::fail("Reference comparison cancelled.");
    report.mixStamp=stamp(report.mixFile);report.copyStamp=stamp(report.referenceCopy);cleanup.keep=true;output=std::move(report);if(progress)progress->store(1);return Result::ok();
}
void ReferenceTask::run(){try{result=compareReference(project,baseFile,reference,settings,folder,report,&cancel,&progress);}catch(const std::exception&){result=juce::Result::fail("Not enough resources to compare reference audio.");}done.store(true,std::memory_order_release);}
}
